  if xb!=yb:different.append({'target':a,'candidate':b,'text':x['text'],'target_bytes':xb.hex(),'candidate_bytes':yb.hex()})
 out={'name':name,'semantic_edits':[[tag,i,j,k,l] for tag,i,j,k,l in ops if tag!='equal'],'aligned_ordinary_byte_differences':different,'aligned_references':refs,'aligned_branches':branches}
 (D/(name+'-regions.json')).write_text(json.dumps(out,indent=2)+'\n')
